function generateBiomeMap(width, height, seed):
    temperature = perlinNoise(width, height, frequency=0.001)
    precipitation = perlinNoise(width, height, frequency=0.002)

    biomeMap = new Array[width][height]

    for y in 0..height:
        for x in 0..width:
            T = temperature[x][y]
            P = precipitation[x][y]
            biomeMap[x][y] = whittakerClassification(T, P)

    // Add Voronoi variation for micro-regions
    sites = generateRandomSites(100, seed)
    voronoi = computeVoronoi(sites, width, height)

    return blend(biomeMap, voronoi, ratio=0.3)
